-- D'FABULOUS STAGING BASELINE, STEP 1: DERIVED BASE SCHEMA  (*** NOT AUTHORITATIVE ***)
-- STATUS: PROPOSAL ONLY. For the dfabulous-staging project ONLY. Never run against production.
--
-- WHY THIS FILE EXISTS
-- The repository's migrations (08 Development/*.sql) assume tables that NO repository file creates: profiles, bookings, messages,
-- payments, services, gallery, testimonials, site_settings (and blocked_dates exists in the repository only in a shape that does not
-- match the application, see docs/STAGING_BASELINE_PLAN.md). The only authoritative definition is the live production schema.
-- PREFERRED PATH: the owner takes a SCHEMA-ONLY dump of production (no data) and installs it in staging INSTEAD of this file, then compares
-- it with this file using supabase/staging/20261112_schema_compare_readonly.sql. This file is the fallback so the repository can be
-- validated end to end without touching production.
--
-- RULES USED: every column below is taken from something the repository actually does, and is labelled:
--   [E] evidenced   : named in repository SQL, or read/written by server.ts / Edge routes / src (the exact use is cited)
--   [A] assumed     : needed for the cited behaviour but its exact type/default/constraint is not stated anywhere (verify against the dump)
-- No data is inserted. No column the repository never mentions is created. Supabase platform defaults (grants to anon/authenticated/
-- service_role on new public tables) apply exactly as they do on a real project; the repository migrations then adjust them.
-- RLS is NOT enabled here; policies, grants and RLS come from the migrations that follow, in the order given by manifest.json.

BEGIN;

-- ---------------------------------------------------------------------------------------------------------------------------------
-- profiles  (referenced by FKs in 20260902_admin_permissions_migration.sql; policies in security_remediation_migration.sql)
-- ---------------------------------------------------------------------------------------------------------------------------------
CREATE TABLE public.profiles (
  id          uuid PRIMARY KEY,   -- [E] REFERENCES public.profiles(id) from user_permissions/audit_logs; WHERE id = auth.uid(); upsert onConflict 'id'
  email       text,               -- [E] WHERE email = 'fabulousevents@hotmail.com' (security_remediation); selected by the API
  full_name   text,               -- [E] selected/upserted by the user-management routes
  role        text,               -- [E] policies/trigger compare role to 'owner'/'admin'; ROLE_OPTIONS in the API
  is_active   boolean,            -- [E] read/written by the API (profile.is_active, .update({ is_active })); defined in NO SQL file; NULL counts as active
  created_at  timestamptz DEFAULT now(),  -- [A] ordered/selected by the API; the API's upsert omits it
  updated_at  timestamptz DEFAULT now()   -- [A] selected by the API; the API's upsert omits it
  -- Not created: any FK to auth.users (the repository never states one), any CHECK on role.
);

-- ---------------------------------------------------------------------------------------------------------------------------------
-- bookings  (public form insert in server.ts; selects in admin routes; create_booking_if_available in 20260815_date_availability.sql)
-- booking_reference is added by 20260902_booking_references.sql; completed_at/archived_at by 20260916_booking_lifecycle_archive.sql.
-- ---------------------------------------------------------------------------------------------------------------------------------
CREATE TABLE public.bookings (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),  -- [E] inserts in server.ts and in create_booking_if_available omit id
  full_name             text,                                        -- [E]
  email                 text,                                        -- [E]
  phone                 text NOT NULL,                               -- [E] 20260902_booking_phone_nullable.sql drops NOT NULL, so it was NOT NULL
  event_date            date,                                        -- [E] gte/lte/in filters, get_unavailable_dates(), date unique index below
  event_location        text,                                        -- [E]
  services_requested    text[],                                      -- [E] create_booking_if_available(p_services_requested text[])
  estimated_guest_count integer,                                     -- [E] create_booking_if_available(p_estimated_guest_count integer)
  celebration_details   text,                                        -- [E]
  status                text,                                        -- [E] 'pending','confirmed','deposit paid','fully paid','completed','cancelled','archived'
  booking_amount        numeric,                                     -- [E] selected, parsed as a currency amount and updated by the admin routes (precision [A])
  currency              text,                                        -- [E] selected/updated; the API tolerates a missing column (42703 retry) so verify in the dump
  created_at            timestamptz DEFAULT now(),                   -- [A] ordered by created_at DESC; the public insert omits it
  updated_at            timestamptz DEFAULT now()                    -- [A] selected; set explicitly by updates
);

-- [A] The API maps unique violation 23505 on an index named bookings_active_event_date_unique (and exclusion violation 23P01) to "Date Unavailable".
-- The name is evidenced (server.ts:838, Edge public.ts); the definition is in no repository file. Predicate taken from the availability logic
-- (get_unavailable_dates, /api/availability): only pending/confirmed bookings hold a date.
CREATE UNIQUE INDEX bookings_active_event_date_unique ON public.bookings (event_date) WHERE status IN ('pending', 'confirmed');

-- ---------------------------------------------------------------------------------------------------------------------------------
-- messages  (contact form insert and admin list/update in server.ts)
-- ---------------------------------------------------------------------------------------------------------------------------------
CREATE TABLE public.messages (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),  -- [A] type not stated; the insert omits it, so it is DB-generated
  full_name   text,                                        -- [E]
  email       text,                                        -- [E]
  phone       text,                                        -- [E]
  subject     text,                                        -- [E]
  message     text,                                        -- [E]
  status      text,                                        -- [E] 'unread' written by the API
  created_at  timestamptz DEFAULT now(),                   -- [A] ordered DESC; insert omits it
  updated_at  timestamptz DEFAULT now()                    -- [A] selected/set by updates
);

-- ---------------------------------------------------------------------------------------------------------------------------------
-- payments  (admin routes; policies in 20260818_payments_rls_hardening.sql; purge function in 20260916_booking_archive_purge_cron.sql)
-- ---------------------------------------------------------------------------------------------------------------------------------
CREATE TABLE public.payments (
  id                     uuid PRIMARY KEY DEFAULT gen_random_uuid(),                       -- [A] type not stated
  booking_id             uuid REFERENCES public.bookings(id) ON DELETE CASCADE,            -- [E] "the production FK is ON DELETE CASCADE" (purge migration); payments.booking_id read
  user_id                uuid,                                                             -- [E] policy: user_id = auth.uid(); insert sets it (FK target not stated)
  amount                 numeric,                                                          -- [E] insert/select; immutability guard
  currency               text,                                                             -- [E]
  payment_type           text,                                                             -- [E] deposit/balance/full/refund
  provider               text,                                                             -- [E] paystack/flutterwave/manual
  status                 text,                                                             -- [E]
  gateway_reference      text,                                                             -- [E]
  gateway_transaction_id text,                                                             -- [E]
  payment_method         text,                                                             -- [E]
  customer_email         text,                                                             -- [E]
  metadata               jsonb DEFAULT '{}'::jsonb,                                        -- [E] object written by the API; default [A]
  paid_at                timestamptz,                                                      -- [E]
  created_at             timestamptz DEFAULT now(),                                        -- [A] ordered DESC; insert omits it
  updated_at             timestamptz DEFAULT now()                                         -- [A] selected
);

-- ---------------------------------------------------------------------------------------------------------------------------------
-- services  (seed: 20260815_seed_services.sql; reads in server.ts and src/lib/db.ts)
-- ---------------------------------------------------------------------------------------------------------------------------------
CREATE TABLE public.services (
  id                text PRIMARY KEY,   -- [E] seed ids are text slugs ('alaga-iduro'); DbService.id: string
  slug              text,               -- [E]
  title             text,               -- [E]
  yoruba_name       text,               -- [E]
  short_description text,               -- [E]
  full_description  text,               -- [E] selected by the admin route
  category          text,               -- [E] 'core' | 'specialist' | 'brand'
  icon_name         text,               -- [E] selected by the admin route
  is_active         boolean,            -- [E] .eq('is_active', true)
  display_order     integer             -- [E] ordered ascending
);

-- ---------------------------------------------------------------------------------------------------------------------------------
-- gallery / testimonials  (public reads via the API; policies in security_remediation_migration.sql; select('*') so columns are the DbGalleryItem/DbTestimonial fields)
-- ---------------------------------------------------------------------------------------------------------------------------------
CREATE TABLE public.gallery (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),  -- [A] src DbGalleryItem.id: string
  title         text,        -- [E] DbGalleryItem
  image_url     text,        -- [E]
  alt_text      text,        -- [E]
  category      text,        -- [E]
  caption       text,        -- [E]
  aspect_ratio  text,        -- [E]
  is_featured   boolean,     -- [E] row?.is_featured
  display_order integer      -- [E] ordered ascending
);

CREATE TABLE public.testimonials (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),  -- [A] src DbTestimonial.id: string
  quote          text,       -- [E] DbTestimonial
  client_names   text,       -- [E]
  event_type     text,       -- [E]
  location       text,       -- [E]
  event_date     date,       -- [A] DbTestimonial.event_date?: string
  rating         integer,    -- [E]
  is_featured    boolean,    -- [E] .eq('is_featured', true)
  is_placeholder boolean,    -- [E]
  display_order  integer     -- [E] ordered ascending
);

-- ---------------------------------------------------------------------------------------------------------------------------------
-- site_settings  (PUT /api/admin/settings, 20260815_admin_settings_privileges.sql, 20260819_public_data_access_hardening.sql)
-- ---------------------------------------------------------------------------------------------------------------------------------
CREATE TABLE public.site_settings (
  key   text PRIMARY KEY,   -- [E] .eq('key', key); ordered by key
  value jsonb               -- [A] the API writes JSON booleans and strings and the dashboard reads both back, so a text column would not round-trip booleans
);

-- ---------------------------------------------------------------------------------------------------------------------------------
-- blocked_dates  LIVE SHAPE (the repository migration 20260815_date_availability.sql creates blocked_date/reason, which the application does not use;
-- git history: "Fix /api/availability to use blocked_dates.event_date matching live"). Policies/grants are installed by the excerpt of that migration.
-- ---------------------------------------------------------------------------------------------------------------------------------
CREATE TABLE public.blocked_dates (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),                -- [A] kept from the repository migration; the API never selects it
  event_date  date NOT NULL UNIQUE,                                       -- [E] insert/delete/select/order by event_date (UNIQUE [A])
  note        text,                                                       -- [E] insert({ event_date, note, created_by })
  created_by  uuid REFERENCES auth.users(id) ON DELETE SET NULL,         -- [E] same FK as the repository migration; policy created_by = auth.uid()
  created_at  timestamptz NOT NULL DEFAULT now(),                         -- [E] selected; default as in the repository migration
  updated_at  timestamptz NOT NULL DEFAULT now()                          -- [A] kept from the repository migration
);

COMMIT;
